method compare(game: array<int>, guess: array<int>) returns (result: array<int>)
    requires game != null && guess != null
    requires |game| == |guess| // Both arrays must be of equal length
    ensures |result| == |game| // Result array length is the same as input arrays
    ensures forall i :: 0 <= i < |result| ==> result[i] == abs(game[i] - guess[i]) // Each element in result is the absolute difference
{
    var n := |game|;
    result := new int[n];

    var i: int;
    for i := 0 to n - 1 {
        result[i] := abs(game[i] - guess[i]);
    }
}
